## TurnManager — the 3-round battle loop (v1: wired to encounter waves + ghost replay).
##
## ROUND STRUCTURE (design doc §1):
##   Round 1: command living squad -> on round end their commands become Ghost Echo 1.
##   Round 2: fresh living squad + Echo 1 replays alongside -> becomes Echo 2.
##   Round 3: fresh living squad + Echo 1 + Echo 2.
## Ghosts replay the SAME command list against the CURRENT board state —
## outcomes can differ from the original round (targets moved), which is the game.
##
## v1 wiring (Nov 3 2026):
## - end_round() now actually STARTS the next round (v0 bug: the loop never advanced).
## - Encounter waves: optional "waves" array (unit list per round); fallback = "units".
## - Ghosts spawn as separate units (id "e<echo>_<unit>") and replay at ROUND START,
##   before the player orders the living squad — deterministic by construction.
## - Objective "rout" evaluated at every round end: all enemies dead = victory;
##   no living/ghost player units left = defeat; 3 rounds survived without rout = defeat.

const ROUNDS: int = 3

var encounter: Dictionary = {}
var sim: RefCounted            # Sim instance for the current round
var ghost_recordings: Array = []   # Array of command-lists, one per past round
var round_number: int = 1
var battle_over: bool = false

signal round_started(round_number: int)
signal round_ended(round_number: int, recording: Array)
signal battle_ended(victory: bool)

func start_battle(enc_data: Dictionary) -> void:
	encounter = enc_data
	round_number = 1
	ghost_recordings = []
	battle_over = false
	_start_round()

func _start_round() -> void:
	sim = load("res://scripts/sim/sim.gd").new(
		int(encounter.get("grid_w", 8)), int(encounter.get("grid_h", 8)),
		int(encounter.get("seed", 0)))
	for u in _wave_units(round_number):
		sim.add_unit(u.duplicate(true))
	_spawn_and_replay_ghosts()
	round_started.emit(round_number)

## Encounter waves: "waves" = array of unit lists, one entry per round.
## If absent (or the battle runs past the list), the "units" wave repeats.
func _wave_units(round: int) -> Array:
	var waves: Array = encounter.get("waves", [])
	if waves.is_empty():
		return encounter.get("units", [])
	var idx: int = clampi(round - 1, 0, waves.size() - 1)
	return waves[idx]

## Ghosts: for each past echo, spawn copies of the recorded squad
## (id "e<echo>_<unit>", flag ghost=true, echo=index) at their round-1 start
## cells, then replay the echo's command list against the CURRENT board.
## sim.replay() applies WITHOUT recording — recordings stay "what the living
## squad did" only. Attack args are cells, untouched: a ghost hits whatever
## occupies the recorded cell — friendly fire ON is the design.
func _spawn_and_replay_ghosts() -> void:
	for echo_index in range(ghost_recordings.size()):
		var recording: Array = ghost_recordings[echo_index]
		var spawned: Dictionary = {}
		for cmd in recording:
			var orig_id: String = cmd["unit_id"]
			if spawned.has(orig_id):
				continue
			var template: Dictionary = _find_unit_template(orig_id)
			if template.is_empty():
				continue
			var ghost: Dictionary = template.duplicate(true)
			ghost["id"] = _ghost_id(echo_index, orig_id)
			ghost["ghost"] = true
			ghost["echo"] = echo_index
			sim.add_unit(ghost)
			spawned[orig_id] = true
		var remapped: Array = []
		for cmd in recording:
			var c: Dictionary = cmd.duplicate(true)
			c["unit_id"] = _ghost_id(echo_index, c["unit_id"])
			remapped.append(c)
		sim.replay(remapped)

func _ghost_id(echo_index: int, unit_id: String) -> String:
	return "e%d_%s" % [echo_index, unit_id]

## Round-1 start state of a unit, from the encounter "units" list — ghosts
## spawn where the squad started.
func _find_unit_template(unit_id: String) -> Dictionary:
	for u in encounter.get("units", []):
		if String(u["id"]) == unit_id:
			return u
	return {}

## Called by the UI/input layer each time the player issues an order.
func on_player_command(unit_id: String, type: String, args: Dictionary) -> void:
	if battle_over or sim == null:
		return
	sim.issue_command(unit_id, type, args)

## Called when the player ends their orders for this round.
func end_round() -> void:
	if battle_over or sim == null:
		return
	# 1. The living squad's commands are recorded forever:
	ghost_recordings.append(sim.commands.duplicate(true))
	round_ended.emit(round_number, sim.commands)
	# 2. Evaluate the objective on the CURRENT board (ghost replay casualties count):
	var outcome: int = _evaluate_objective()
	if outcome == 1:
		battle_over = true
		battle_ended.emit(true)
		return
	if outcome == -1:
		battle_over = true
		battle_ended.emit(false)
		return
	# 3. Rounds exhausted without a rout = defeat; otherwise next round.
	if round_number >= ROUNDS:
		battle_over = true
		battle_ended.emit(false)
		return
	round_number += 1
	_start_round()

## Objective v1: "rout" — all enemies dead.
## Returns 1 (victory), -1 (defeat: nothing of ours left), 0 (keep going).
func _evaluate_objective() -> int:
	var enemies_alive: int = 0
	var ours_alive: int = 0
	for id in sim.units.keys():
		var u: Dictionary = sim.units[id]
		if not u["alive"]:
			continue
		if String(u.get("faction", "player")) == "enemy":
			enemies_alive += 1
		else:
			ours_alive += 1
	if enemies_alive == 0:
		return 1
	if ours_alive == 0:
		return -1
	return 0

## Ghost preview (design doc §3): the recorded commands of echo `index`,
## annotated for the UI. UI renders these as translucent intents.
func preview_echo(index: int) -> Array:
	if index < 0 or index >= ghost_recordings.size():
		return []
	return ghost_recordings[index]
